// src/export/rn-compat.ts -- version pins for name-only bare-RN dependencies, from
// the table vendored at rn-compat.json (generated by tools/gen-rn-compat.mjs from
// the npm registry: every package's declared `react-native` peer range per
// version, plus a publish timeline and the release date of each RN minor).
import { readFileSync } from "node:fs";

interface PackageEntry {
  readonly peers: readonly (readonly [string, string])[]; // [newest version carrying the range, range]
  readonly months: readonly (readonly [string, string])[]; // [YYYY-MM, newest stable version published that month]
}
interface Table {
  readonly generatedOn: string;
  readonly rn: Readonly<Record<string, string>>; // "0.73" -> release date of that minor's last patch
  readonly rnReact?: Readonly<Record<string, readonly [string, string]>>; // "0.78" -> [newest patch, its `react` peer range]
  readonly packages: Readonly<Record<string, PackageEntry>>;
}
let cache: Table | null = null;
function table(): Table {
  cache ??= JSON.parse(readFileSync(new URL("./rn-compat.json", import.meta.url), "utf8")) as Table;
  return cache;
}

type Ver = readonly [number, number, number];
function parseVer(s: string): Ver | null {
  const m = /^v?(\d+)(?:\.(\d+|[xX*]))?(?:\.(\d+|[xX*]))?(?:-[0-9A-Za-z.-]+)?$/.exec(s.trim());
  if (m === null) return null;
  const n = (x: string | undefined): number => (x === undefined || /[xX*]/.test(x) ? -1 : Number(x));
  return [Number(m[1]), n(m[2]), n(m[3])];
}
function cmpVer(a: Ver, b: Ver): number {
  for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i]! - b[i]!;
  return 0;
}
const fill = (v: Ver): Ver => [v[0], Math.max(v[1], 0), Math.max(v[2], 0)];

/** Whether npm-style semver `range` admits `version` (a stable M.m.p). Handles `||`,
 *  AND-ed comparators, hyphen ranges, `^`, `~`, `x`-ranges, `*`. Anything it cannot
 *  parse does not admit (the caller then falls back to the timeline). */
export function satisfies(version: string, range: string): boolean {
  const v = parseVer(version);
  if (v === null || v[1] < 0 || v[2] < 0) return false;
  for (const alt of range.split("||")) {
    const text = alt.trim();
    if (text === "" || text === "*" || text === "x") return true;
    const hyphen = /^(\S+)\s+-\s+(\S+)$/.exec(text);
    const comps = hyphen !== null ? [`>=${hyphen[1]}`, `<=${hyphen[2]}`] : text.replace(/([<>=~^])\s+/g, "$1").split(/\s+/);
    let ok = true;
    for (const c of comps) {
      if (!compOk(v, c)) {
        ok = false;
        break;
      }
    }
    if (ok) return true;
  }
  return false;
}
function compOk(v: Ver, c: string): boolean {
  const m = /^(>=|<=|>|<|=|\^|~)?(.+)$/.exec(c);
  if (m === null) return false;
  const op = m[1] ?? "";
  const t = parseVer(m[2]!);
  if (t === null) return false;
  const lo = fill(t);
  switch (op) {
    case ">=": return cmpVer(v, lo) >= 0;
    case ">": return t[2] >= 0 ? cmpVer(v, lo) > 0 : t[1] >= 0 ? v[0] > t[0] || (v[0] === t[0] && v[1] > t[1]) : v[0] > t[0];
    case "<=": return t[2] < 0 ? (t[1] < 0 ? v[0] <= t[0] : v[0] < t[0] || (v[0] === t[0] && v[1] <= t[1])) : cmpVer(v, lo) <= 0;
    case "<": return cmpVer(v, lo) < 0;
    case "~": return cmpVer(v, lo) >= 0 && (t[1] < 0 ? v[0] === t[0] : v[0] === t[0] && v[1] === t[1]);
    case "^": {
      if (cmpVer(v, lo) < 0) return false;
      if (t[0] > 0 || t[1] < 0) return v[0] === t[0];
      if (t[1] > 0 || t[2] < 0) return v[0] === 0 && v[1] === t[1];
      return v[0] === 0 && v[1] === 0 && v[2] === t[2];
    }
    default: // "" or "=": exact, or x-range
      return v[0] === t[0] && (t[1] < 0 || v[1] === t[1]) && (t[2] < 0 || v[2] === t[2]);
  }
}

export interface RnPin {
  readonly version: string;
  readonly note: string;
}

/** The pin for `pkg` under React Native `rnVersion`, or null when the table does not know `pkg`.
 *  1. the newest version whose declared react-native peer range admits `rnVersion`;
 *  2. else the newest version published by the end of that RN minor's last patch month
 *     (packages that declare no react-native peer, or none that admits it). */
export function rnCompatPin(pkg: string, rnVersion: string): RnPin | null {
  const t = table();
  const entry = t.packages[pkg];
  if (entry === undefined) return null;
  // A wildcard react-native peer (`*`) says nothing about which RN a version
  // was built for: corpus a08 (RN 0.66.4) got reanimated 4.2.2, gesture
  // handler 3.5.0 and @react-navigation/native 7.5.2 (peer react >= 18.2,
  // ERESOLVE beside RN 0.66's react 17) because their newest versions declare
  // `*`. A wildcard admits a version only up to the newest one published by
  // the end of the RN line (rule 2's pin); newer ones fall through to rule 2.
  const timeBound = pinByTime(t, entry, rnVersion);
  let best: string | null = null;
  for (const [v, range] of entry.peers) {
    if (!satisfies(rnVersion, range)) continue;
    if (isWildcardRange(range) && (timeBound === null || cmpVer(parseVer(v)!, parseVer(timeBound.version)!) > 0)) continue;
    const pv = parseVer(v)!;
    if (best === null || cmpVer(pv, parseVer(best)!) > 0) best = v;
  }
  if (best !== null) {
    const range = entry.peers.find(([v]) => v === best)![1];
    return { version: best, note: `newest version whose react-native peer range (${range}) admits ${rnVersion} (rn-compat.json, npm registry, ${t.generatedOn})` };
  }
  if (timeBound === null) return null;
  return { version: timeBound.version, note: `newest version published by ${timeBound.month} (end of the RN ${minorOf(rnVersion)} line); declares no specific react-native peer range admitting ${rnVersion} (rn-compat.json, npm registry, ${t.generatedOn})` };
}

/** `*`, `x`, empty, or `>=0`: a range that admits every react-native. */
function isWildcardRange(range: string): boolean {
  return /^\s*(\*|x|X|>=\s*0(\.0)*(\.0)?)?\s*$/.test(range);
}

/** Rule 2: the newest version published by the end of the RN line. */
function pinByTime(t: Table, entry: Table["packages"][string], rnVersion: string): { readonly version: string; readonly month: string } | null {
  const released = t.rn[minorOf(rnVersion)];
  if (released === undefined) return null;
  const month = released.slice(0, 7);
  let byTime: string | null = null;
  for (const [ym, v] of entry.months) if (ym <= month) byTime = v;
  return byTime === null ? null : { version: byTime, month };
}

const minorOf = (v: string): string => v.split(".").slice(0, 2).join(".");
function rnReactRows(): [string, string, string][] {
  // [minor, newest patch, react peer range], ascending; drops the 1000.x placeholder line.
  return Object.entries(table().rnReact ?? {})
    .filter(([m]) => /^0\./.test(m))
    .map(([m, [v, r]]) => [m, v, r] as [string, string, string])
    .sort((a, b) => cmpVer(parseVer(a[1])!, parseVer(b[1])!));
}

/** The `react` peer range react-native `rnVersion`'s minor line declares (its newest patch), or null if unknown. */
export function rnReactPeer(rnVersion: string): string | null {
  return table().rnReact?.[minorOf(rnVersion)]?.[1] ?? null;
}

/** Whether react `reactVersion` installs beside react-native `rnVersion` (true when the table does not know the RN line). */
export function reactFitsRn(reactVersion: string, rnVersion: string): boolean {
  const range = rnReactPeer(rnVersion);
  return range === null || parseVer(reactVersion) === null || satisfies(reactVersion, range);
}

/** The react-native release (newest patch of its minor) whose `react` peer admits
 *  `reactVersion`, nearest by minor to `near` (ties: the older line), optionally
 *  limited to `[minMinor, maxMinor]`. Null when no line admits it. */
export function rnForReact(reactVersion: string, near: string | null, minMinor?: number, maxMinor?: number): RnPin | null {
  const nearMinor = near !== null ? Number(minorOf(near).split(".")[1]) : null;
  let best: [string, string, string] | null = null;
  let bestDist = Infinity;
  for (const row of rnReactRows()) {
    const minor = Number(row[0].split(".")[1]);
    if ((minMinor !== undefined && minor < minMinor) || (maxMinor !== undefined && minor > maxMinor)) continue;
    if (!satisfies(reactVersion, row[2])) continue;
    const dist = nearMinor === null ? -minor : Math.abs(minor - nearMinor);
    if (dist < bestDist) {
      best = row;
      bestDist = dist;
    }
  }
  if (best === null) return null;
  return { version: best[1], note: `react ${reactVersion} needs RN whose react peer admits it; RN ${best[0]} declares react ${best[2]} (rn-compat.json rnReact, npm registry, ${table().generatedOn})` };
}
